const fs=require('node:fs'),path=require('node:path');const {ts}=require('./register.cjs');const root=path.resolve(__dirname,'..');let files=0,errors=0;
function visit(dir){for(const name of fs.readdirSync(dir)){const full=path.join(dir,name);if(fs.statSync(full).isDirectory()){if(!['node_modules','.next','preview','.git'].includes(name))visit(full)}else if(/\.(ts|tsx)$/.test(name)&&!name.endsWith('.d.ts')){files++;const result=ts.transpileModule(fs.readFileSync(full,'utf8'),{fileName:full,compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext,jsx:ts.JsxEmit.ReactJSX},reportDiagnostics:true});for(const d of result.diagnostics||[]){if(d.category===ts.DiagnosticCategory.Error){errors++;console.error(path.relative(root,full)+': '+ts.flattenDiagnosticMessageText(d.messageText,' '))}}}}}
for(const dir of ['app','components','lib'])visit(path.join(root,dir));console.log(`Syntax-transpiled ${files} TS/TSX source files; ${errors} syntax errors. This does not resolve framework types or verify the Next build.`);process.exitCode=errors?1:0;
